# -*- coding: utf-8 -*-
# Tarjetas de la pestaña Historia. [[k:...]] = naranja (frase clave); [[a:...]] = azul (matiz o lo que juega en contra).
# Campos extra: year (fecha de muerte), who, postura (columna «Postura» de la tabla).

KSU_T = "https://quran.ksu.edu.sa/tafseer/tabary/"
KSU_K = "https://quran.ksu.edu.sa/tafseer/katheer/sura3-aya78.html"
