IW = "islamweb.net"

HCARDS = [
 dict(id="H01", year="23 H", who="Umar, según al-Shaʿbi", postura="Positiva",
  title="«Me maravillaba de cómo la Torá confirma el Corán, y el Corán la Torá»",
  ref="al-Tabari, Tafsir, sobre el Corán 2:97, n.º 1608 y 1609", ar_ref="تفسير الطبري، البقرة ٩٧، رقم ١٦٠٨–١٦٠٩", site=KSU, url=KSU_T+"sura2-aya97.html",
  es=["1608 — Me contó Muhammad ibn al-Muthanna: nos contó Ribʿi ibn ʿUlayya, de Dawud ibn Abi Hind, de al-Shaʿbi, que dijo: Umar acampó en al-Rawhaʾ y vio a unos hombres que se apresuraban hacia unas piedras para rezar junto a ellas. Dijo: «¿Qué hacen estos?». Dijeron: «Dicen que el Mensajero de Dios ﷺ rezó aquí». Le desagradó y dijo: «[No es más que esto:] al Mensajero de Dios ﷺ le llegó la hora de la oración en un valle, rezó y luego partió y lo dejó». Luego se puso a contarles y dijo: «[[k:Yo asistía a los judíos el día de su estudio, y me maravillaba de cómo la Torá confirma el Furqán [el Corán], y de cómo el Furqán confirma la Torá]]».",
      "1609 — Me contó Yaʿqub ibn Ibrahim: nos contó Ibn ʿUlayya, de Dawud, de al-Shaʿbi, que dijo: dijo Umar: «[[k:Yo era un hombre que frecuentaba a los judíos el día de su estudio]]»; y mencionó algo parecido al relato de Ribʿi."],
  prueba="Es el recuerdo más antiguo que se conserva de un compañero ante la Torá que se leía en Medina: Umar la escuchaba y veía que confirmaba el Corán.",
  ojo="Al-Shaʿbi no conoció a Umar: la cadena es sólida hasta al-Shaʿbi y está cortada después (mursal). Detalles en el Vídeo 2, bloque 8, y en IH16 e IH17."),

 dict(id="H02b", year="68 H", who="Ibn Abbas", postura="Interpretación + libros añadidos",
  title="La otra narración: «cambiaron el Libro de Dios… y escribieron con sus manos»",
  ref="Sahih al-Bujari 7363 (Kitab al-Iʿtisam)", ar_ref="صحيح البخاري ٧٣٦٣", site="hadithunlocked.com", url="https://hadithunlocked.com/bukhari:7363",
  es=["«¿Cómo preguntáis a la Gente del Libro por algo, cuando vuestro Libro, revelado al Mensajero de Dios ﷺ, es el más reciente? Lo recitáis puro, sin mezcla. Y [vuestro Libro] os ha contado que la Gente del Libro [[k:cambió el Libro de Dios y lo alteró]], [[k:y escribieron con sus manos el libro y dijeron: “Esto viene de Dios”]], para venderlo a bajo precio. ¿No os impide el saber que os ha llegado preguntarles? No, por Dios: no hemos visto a ninguno de ellos preguntaros por lo que se os ha revelado.»"],
  prueba="Es la narración que usa Tibyanan, y es real. Es palabra de Ibn Abbas (mawquf) y parafrasea el Corán 2:79: «¡ay de quienes escriben el libro con sus manos y luego dicen: esto viene de Dios!».",
  ojo="Hay que mostrarla entera. Junto con la glosa de Ibn Atiyya (H02a) da la postura de la tabla: interpretación + libros añadidos. Cómo se armonizan las dos: IH09 y Vídeo 1, bloque 6."),

 dict(id="H03", year="90 H", who="Abu al-ʿAliya", postura="Cambio local",
  title="«Fueron a la descripción de Muhammad en su libro y la desplazaron de su lugar»",
  ref="al-Tabari, Tafsir, sobre el Corán 2:79, n.º 1394", ar_ref="تفسير الطبري، البقرة ٧٩، رقم ١٣٩٤", site=KSU, url=KSU_T+"sura2-aya79.html",
  es=["1394 — Me contó al-Muthanna: nos contó Adam: nos contó Abu Jaʿfar, de al-Rabiʿ, de Abu al-ʿAliya, sobre Su palabra «¡Ay de quienes escriben el libro con sus manos y luego dicen: esto viene de Dios, para venderlo a bajo precio!»: dijo: «[[k:Fueron a la descripción de Muhammad ﷺ que Dios había revelado en su libro y la desplazaron de su lugar]], buscando con ello un bien de esta vida». Y dijo [Dios]: «¡Ay de ellos por lo que escribieron sus manos, y ay de ellos por lo que ganan!»."],
  prueba="Voz temprana de un cambio concreto: la descripción de Muhammad. No dice que toda la Torá esté falsificada.",
  ojo="Este texto juega en contra de la versión fuerte («nadie habló de cambios en el texto»). La tesis que aguanta es «nadie habla de falsificación total en los dos primeros siglos»."),

 dict(id="H04", year="104 H", who="Mujahid", postura="Ambiguo",
  title="«Los que la tergiversan y los que la ocultan son sus sabios»",
  ref="al-Tabari, Tafsir, sobre el Corán 2:75, n.º 1328", ar_ref="تفسير الطبري، البقرة ٧٥، رقم ١٣٢٨", site=KSU, url=KSU_T+"sura2-aya75.html",
  es=["1328 — Me lo contó Muhammad ibn ʿAmr: nos contó Abu ʿAsim: nos contó ʿIsa, de Ibn Abi Najih, de Mujahid, sobre la palabra de Dios «¿Esperáis que os crean, cuando un grupo de ellos escuchaba la palabra de Dios y luego la tergiversaba después de haberla entendido, a sabiendas?»: [[k:los que la tergiversan y los que la ocultan son sus sabios]]."],
  prueba="Mujahid (m. 104 H), alumno de Ibn Abbas, dice quién tergiversa (los sabios) y lo une a ocultar, pero no dice cómo. Por eso la tabla lo marca como ambiguo."),

 dict(id="H05", year="c. 114 H", who="Wahb ibn Munabbih", postura="Interpretación + libros añadidos",
  title="«No se ha cambiado ni una letra»",
  ref="Ibn Kathir, Tafsir, sobre el Corán 3:78 (de Ibn Abi Hatim)", ar_ref="تفسير ابن كثير، آل عمران ٧٨", site=KSU, url=KSU_K,
  es=["Y dijo Wahb ibn Munabbih: «[[k:La Torá y el Evangelio, tal como Dios los reveló, no han sido cambiados en una sola letra]]; [[k:pero extravían [a la gente] con la tergiversación y la interpretación, y con libros que escribían ellos mismos]], “y dicen: viene de Dios, y no viene de Dios”. [[k:En cuanto a los libros de Dios, están preservados y no cambian]]». Lo transmitió Ibn Abi Hatim."],
  prueba="Wahb (m. c. 114 H), alumno de Ibn Abbas y de los que más sabían de la Torá: ni una letra cambiada; el extravío viene de la interpretación y de libros que ellos escribían.",
  ojo="Ibn Kathir no lo comparte para su propia época; lo explica justo después (H18)."),

 dict(id="H06", year="117 H", who="Qatada", postura="Libros añadidos",
  title="«Escribieron un libro con sus manos… y dijeron: esto viene de Dios»",
  ref="al-Tabari, Tafsir, sobre el Corán 2:79, n.º 1393", ar_ref="تفسير الطبري، البقرة ٧٩، رقم ١٣٩٣", site=KSU, url=KSU_T+"sura2-aya79.html",
  es=["1393 — Nos contó al-Hasan ibn Yahya: nos informó ʿAbd al-Razzaq: nos informó Maʿmar, de Qatada, sobre Su palabra «¡Ay de quienes escriben el libro con sus manos y luego dicen: esto viene de Dios!»: dijo: «[[k:Había gente de los hijos de Israel que escribió un libro con sus manos para aprovecharse de la gente, y dijeron: esto viene de Dios; y no venía de Dios]]»."],
  prueba="Qatada (m. 117 H) lee el Corán 2:79 como un libro nuevo escrito por ellos, no como un cambio dentro del texto de la Torá."),

 dict(id="H08", year="182 H", who="Ibn Zayd", postura="Libro falso junto al verdadero",
  title="Tenían «el Libro de Dios» y «ese otro libro», y sacaban uno u otro según el soborno",
  ref="al-Tabari, Tafsir, sobre el Corán 2:75, n.º 1331", ar_ref="تفسير الطبري، البقرة ٧٥، رقم ١٣٣١", site=KSU, url=KSU_T+"sura2-aya75.html",
  es=["1331 — Nos contó Yunus: nos informó Ibn Wahb: dijo Ibn Zayd, sobre Su palabra «escuchaban la palabra de Dios y luego la tergiversaban»: dijo: «La Torá que Él les reveló: la tergiversaban; [[a:hacían en ella de lo lícito ilícito y de lo ilícito lícito]], de lo verdadero falso y de lo falso verdadero. [[k:Cuando venía a ellos el que tenía razón con un soborno, le sacaban el Libro de Dios; y cuando venía el que no la tenía con un soborno, le sacaban aquel [otro] libro]], y en él tenía razón. Y si venía alguien a preguntarles algo sin derecho ni soborno ni nada, le mandaban lo justo»."],
  prueba="Para Ibn Zayd (m. 182 H) el Libro de Dios seguía en sus manos; junto a él tenían «ese otro libro», que sacaban según el soborno.",
  ojo="También dice que «hacían de lo lícito ilícito» (en azul): es tergiversar el juicio, sin decir que el Libro de Dios desapareciera."),

 dict(id="H09", year="256 H", who="al-Bujari", postura="Interpretación",
  title="«Nadie elimina el texto de un libro de Dios; lo tergiversan interpretándolo»",
  ref="Sahih al-Bujari, Kitab al-Tawhid (texto del capítulo), y Fath al-Bari 13/533", ar_ref="صحيح البخاري، كتاب التوحيد · فتح الباري ١٣/٥٣٣", site=IW, url=F13,
  es=["Capítulo de la palabra de Dios: «Es un Corán glorioso, en una Tabla preservada», y «Por el monte, y por un Libro escrito». Dijo Qatada: «escrito»; «yasṭurūn»: trazan; «en la Madre del Libro»: el conjunto del Libro y su origen; «no pronuncia»: no dice nada sin que se le anote. Y dijo Ibn Abbas: se anota el bien y el mal. «[[k:Yuḥarrifūn: yuzīlūn (tergiversan: eliminan). Y nadie elimina el texto de un libro de entre los libros de Dios, poderoso y majestuoso, sino que lo tergiversan: lo interpretan de una forma que no es su interpretación]]».",
      "Dijo nuestro maestro Ibn al-Mulaqqin en su comentario: «[[k:Esto que dijo es una de las dos opiniones sobre la interpretación de este versículo, y es la que él eligió]] —es decir, al-Bujari—. Muchos de nuestros compañeros han declarado expresamente que los judíos y los cristianos cambiaron la Torá y el Evangelio, y de ello dedujeron que es lícito tratar sus hojas sin respeto; y eso contradice lo que dice aquí al-Bujari». Fin de la cita."],
  prueba="Bujari (m. 256 H) recoge en su Sahih, bajo «y dijo Ibn Abbas», que nadie elimina el texto de los libros de Dios. Sea de Ibn Abbas o suya, Ibn al-Mulaqqin dice que es la opinión que eligió Bujari.",
  ojo="Si la frase es de Ibn Abbas o un añadido de Bujari está discutido: IH01, IH03 e IH08."),

 dict(id="H13b", year="456 H", who="Ibn Hazm (citado por Ibn Hajar)", postura="Texto alterado",
  title="«Nos ha llegado que hay musulmanes que niegan que estén alterados»",
  ref="Ibn Hajar, Fath al-Bari 13/534, citando a Ibn Hazm, al-Fisal", ar_ref="فتح الباري ١٣/٥٣٤ نقلًا عن الفصل لابن حزم", site=IW, url=F13,
  es=["[[k:Abu Muhammad ibn Hazm]] enumeró en su libro al-Fisal fi l-milal wa-l-nihal muchas cosas de este tipo…",
      "Luego citó cosas del texto de la Torá que tienen ahora en sus manos, en las que la mentira es muy evidente. Y después dijo: «[[k:Nos ha llegado que hay un grupo de musulmanes que niegan que la Torá y el Evangelio que tienen en sus manos los judíos y los cristianos estén alterados]]; [[a:y lo que les lleva a eso es lo poco que les importan los textos del Corán y de la Sunna]]»."],
  prueba="El sistematizador de la falsificación total (m. 456 H) reconoce que en su tiempo había musulmanes que la negaban. Sus pruebas son de contenido (pasajes que considera falsos), no manuscritos.",
  ojo="Ibn Hazm descalifica a esos musulmanes (en azul): muestra la frase entera. El texto original de al-Fisal está en H13a."),

 dict(id="H17", year="728 H", who="Ibn Taymiyya", postura="Parcial",
  title="«Cada una de estas dos opiniones la han sostenido muchos musulmanes»",
  ref="Ibn Taymiyya, Majmuʿ al-Fatawa 13/103–104 (ed. Ibn Qasim)", ar_ref="مجموع الفتاوى ١٣/١٠٣–١٠٤", site="ar.wikisource.org (transcripción del texto)", url="https://ar.wikisource.org/wiki/مجموع_الفتاوى/المجلد_الثالث_عشر/فصل_في_تحريف_الإنجيل",
  es=["Ya se dijo antes de esto que se ha afirmado: «No hay en el mundo un ejemplar con lo mismo que Dios reveló en la Torá y el Evangelio; todo eso está cambiado, porque la transmisión masiva (tawātur) de la Torá se interrumpió, y el Evangelio se tomó de cuatro [personas]». Entre quienes lo dicen, unos sostienen que mucho de lo que hay en la Torá o el Evangelio es falso y no es palabra de Dios, y otros dicen: «no, eso es poco». [[k:Y se ha dicho: nadie alteró ni una de las letras de los libros; solo alteraron sus sentidos con la interpretación]]. [[k:Y cada una de estas dos opiniones la han sostenido muchos musulmanes]]. Lo correcto es la tercera opinión: [[k:que en la tierra había ejemplares auténticos, que perduraron hasta la época del Profeta ﷺ]], [[a:y muchos ejemplares alterados]]. Quien dice que no se alteró ninguno de los ejemplares afirma algo que no puede probar; y [[k:quien dice que todos los ejemplares se alteraron después del Profeta ﷺ dice algo que se sabe que es un error]], pues el Corán les manda juzgar por lo que Dios reveló en la Torá y el Evangelio, e informa de que en ellos está Su juicio; [[k:y no hay en el Corán ninguna noticia de que cambiaran todos los ejemplares]]."],
  prueba="Ibn Taymiyya (m. 728 H), autor de la gran refutación clásica del cristianismo, reconoce que la opinión «ni una letra alterada» la sostenían muchos musulmanes, y rechaza que todos los ejemplares se corrompieran después del Profeta.",
  ojo="Él cree que había muchos ejemplares alterados (en azul). La página de wikisource no muestra el número de página; la referencia impresa es 13/103–104."),

 dict(id="H18", year="774 H", who="Ibn Kathir", postura="Texto alterado (en su época)",
  title="«No hay duda de que ha entrado en ello el cambio»… y las traducciones árabes, llenas de errores",
  ref="Ibn Kathir, Tafsir, sobre el Corán 3:78", ar_ref="تفسير ابن كثير، آل عمران ٧٨", site=KSU, url=KSU_K,
  es=["Si Wahb se refería a lo que tienen en sus manos, [[k:no hay duda de que en ello han entrado el cambio, la tergiversación, la adición y la supresión]]; [[k:y en cuanto a la traducción al árabe que circula, tiene grandes errores, muchas adiciones y supresiones, y graves equivocaciones]]. Es del tipo de la interpretación del traductor que arabiza, y la comprensión de muchos de ellos —o más bien de la mayoría, o de todos— es corrupta. Pero si se refería a los libros de Dios tal como son de parte de Él, [[a:esos, como dijo, están preservados y no ha entrado en ellos nada]]."],
  prueba="Ibn Kathir (m. 774 H) cree que en los ejemplares de su época hay cambios, adiciones y supresiones, y que las traducciones árabes están llenas de errores: la postura «texto alterado (en su época)».",
  ojo="Matiz (en azul): no niega que lo revelado por Dios esté preservado; habla de los ejemplares y traducciones de su tiempo."),

 dict(id="H19b", year="804 H", who="Ibn al-Mulaqqin (citado por Ibn Hajar)", postura="Texto alterado (mayoritario en su escuela)",
  title="«Muchos de nuestros compañeros declararon que cambiaron la Torá y el Evangelio»",
  ref="Ibn Hajar, Fath al-Bari 13/533, citando a Ibn al-Mulaqqin", ar_ref="فتح الباري ١٣/٥٣٣ نقلًا عن ابن الملقن", site=IW, url=F13,
  es=["Dijo nuestro maestro Ibn al-Mulaqqin en su comentario: «[[a:Esto que dijo es una de las dos opiniones sobre la interpretación de este versículo, y es la que él eligió]] —es decir, al-Bujari—. [[k:Muchos de nuestros compañeros han declarado expresamente que los judíos y los cristianos cambiaron la Torá y el Evangelio]], y de ello dedujeron que es lícito tratar sus hojas sin respeto; y eso contradice lo que dice aquí al-Bujari». Fin de la cita."],
  prueba="Ibn al-Mulaqqin (m. 804 H) da fe de que en su escuela (shafiʿí) muchos sostenían que se cambió la Torá y el Evangelio; y a la vez reconoce (en azul) que la opinión contraria es la que eligió Bujari.",
  ojo="El texto original, en su propio comentario (al-Tawdih), está en H19a."),

 dict(id="H21", year="852 H", who="Ibn Hajar", postura="Abierto",
  title="Recoge cuatro opiniones y se niega a llamar falsa la de «solo el sentido»",
  ref="Ibn Hajar, Fath al-Bari 13/533–534", ar_ref="فتح الباري لابن حجر ١٣/٥٣٣–٥٣٤", site=IW, url=F13,
  es=["Dijo uno de los comentaristas tardíos: sobre esta cuestión hay varias opiniones. [[k:Primera: que fue cambiada entera]]; es lo que implica la opinión, ya citada, de que se puede tratar [sus hojas] sin respeto, y es un exceso. Hay que entender que quienes lo dicen de forma absoluta se refieren a la mayor parte; si no, es negar lo evidente, y los versículos y los relatos que dicen que de ella quedaron muchas cosas sin cambiar son muchos. Entre ellos, la palabra de Dios: «los que siguen al Mensajero, el Profeta iletrado, al que encuentran escrito junto a ellos en la Torá y el Evangelio»; y la historia de la lapidación de los dos judíos, en la que aparece el versículo de la lapidación; y lo apoya la palabra de Dios: «Di: traed la Torá y leedla, si sois sinceros». [[k:Segunda: que el cambio se produjo, pero en la mayor parte de ella]]; sus pruebas son muchas, y la primera hay que entenderla así. [[k:Tercera: que se produjo en una pequeña parte y la mayor parte sigue como estaba]]; la defendió el shaykh Taqi al-Din ibn Taymiyya en su libro al-Jawab al-sahih li-man baddala din al-Masih. [[k:Cuarta: que el cambio y la alteración se produjeron solo en los sentidos, no en las palabras; y es la que se menciona aquí]].",
      "[[k:Y calificar de falsa esa opinión, con lo expuesto, también es objetable]]: se ha atribuido a Wahb ibn Munabbih, que es de los que más sabían de la Torá, [[k:y se ha atribuido también a Ibn Abbas, el intérprete del Corán]]. Debería haber dejado de rechazarla a empujones…"],
  prueba="Ibn Hajar (m. 852 H) expone las cuatro opiniones sin quedarse con una, y se niega a llamar falsa la de «solo el sentido».",
  ojo="Las cuatro opiniones las expone citando a «uno de los comentaristas tardíos». Más contexto: IH02 e IH10."),
]

SH = "shamela.ws (Maktaba Shamila; paginación igual a la edición impresa)"
HCARDS += [
 dict(id="H03x", year="Extra", who="Relato atribuido al Profeta vía ʿUthman (no está en la tabla)", postura="Texto alterado (relato que Ibn Kathir no acepta)",
  title="«Tergiversaron la Torá, añadieron… y borraron el nombre de Muhammad»: Ibn Kathir lo llama «muy extraño»",
  ref="Ibn Kathir, Tafsir, sobre el Corán 2:79 (también en al-Tabari 2:79, n.º 1395)", ar_ref="تفسير ابن كثير، البقرة ٧٩", site=KSU, url="https://quran.ksu.edu.sa/tafseer/katheer/sura2-aya79.html",
  es=["[…] de ʿUthman ibn ʿAffan, del Mensajero de Dios ﷺ, sobre «¡Ay de ellos por lo que escribieron sus manos, y ay de ellos por lo que ganan!»: dijo: «El “ay” (wayl) es un monte en el Fuego, y es lo que se reveló sobre los judíos, [[a:porque tergiversaron la Torá, añadieron en ella lo que quisieron, borraron de ella lo que no les gustaba y borraron de la Torá el nombre de Muhammad ﷺ]]. Por eso Dios se enfadó con ellos y retiró parte de la Torá», y dijo: «¡Ay de ellos por lo que escribieron sus manos, y ay de ellos por lo que ganan!». [[k:Y esto también es muy extraño]] (gharīb jiddan)."],
  prueba="Es el único relato que pone en boca del Profeta que borraron y añadieron en la Torá. Ibn Kathir, que lo transmite, lo califica de «muy extraño» (gharīb jiddan): un relato aislado que no da por fiable.",
  ojo="No está en la tabla, pero conviene tenerlo a mano: si Tibyanan lo presenta como «palabra del Profeta», la respuesta es el juicio de Ibn Kathir. Revisa su cadena antes de usarlo (al-Tabari 2:79, n.º 1395)."),

 dict(id="H07a", year="150 H", who="Muqatil ibn Sulayman", postura="Cambio local",
  title="«Los jefes de los judíos de Medina borraron de la Torá la descripción de Muhammad»",
  ref="Muqatil ibn Sulayman, Tafsir, sobre el Corán 2:79, vol. 1, p. 118 (ed. Shihata)", ar_ref="تفسير مقاتل بن سليمان ١/١١٨", site=SH, url="https://shamela.ws/book/23614/49",
  es=["«¡Ay de quienes escriben el libro con sus manos!»: algo distinto de la descripción de Muhammad ﷺ. [[k:Y es que los jefes de los judíos de Medina borraron de la Torá la descripción de Muhammad ﷺ]] y escribieron otra en su lugar, y dijeron a los judíos algo distinto de la descripción de Muhammad. «Y luego dicen»: esta descripción «viene de Dios, para venderlo a bajo precio», es decir, el pequeño beneficio que la gente humilde de los judíos les daba cada año de sus cosechas y sus frutos. Dice: «¡Ay de ellos por lo que escribieron sus manos!», es decir, en la Torá, [[k:al cambiar la descripción de Muhammad]] ﷺ."],
  prueba="Muqatil (m. 150 H) sí habla de un cambio en el texto: borraron la descripción de Muhammad y escribieron otra. Es un cambio concreto, no la falsificación de toda la Torá.",
  ojo="Este texto juega en contra de la versión fuerte de la tesis; muéstralo. Matices: su tafsir nos llega en una recensión posterior (de al-Hudhayl ibn Habib), y Muqatil fue muy criticado como transmisor por los especialistas en hadiz."),

 dict(id="H07b", year="150 H", who="Muqatil ibn Sulayman", postura="Cambio local",
  title="«Escribieron en la Torá algo distinto de la descripción de Muhammad y borraron su descripción»",
  ref="Muqatil ibn Sulayman, Tafsir, sobre el Corán 3:78, vol. 1, p. 286 (ed. Shihata)", ar_ref="تفسير مقاتل بن سليمان ١/٢٨٦", site=SH, url="https://shamela.ws/book/23614/193",
  es=["«Retuercen sus lenguas con el Libro»: [[k:con «retorcer» se refiere a la tergiversación con las lenguas]] en lo relativo a Muhammad ﷺ; «para que lo creáis parte del Libro», es decir, de la Torá. Dice Dios, poderoso y majestuoso: «y no es parte del Libro»: [[k:escribieron —es decir, en la Torá— algo distinto de la descripción de Muhammad ﷺ]] [[k:y borraron su descripción]]; «y dicen: es» —esta descripción— «de parte de Dios, y no es de parte de Dios», sino que la escribieron ellos."],
  prueba="Aquí Muqatil junta las dos cosas: tergiversar con la lengua al recitar y, en concreto, cambiar por escrito la descripción de Muhammad. Siempre sobre ese punto, no sobre el conjunto de la Torá."),

 dict(id="H11a", year="310 H", who="al-Tabari (opinión propia)", postura="Mixta",
  title="«Los rabinos escriben mentiras con sus manos y las hacen pasar por el Libro de Dios»",
  ref="al-Tabari, Tafsir, sobre el Corán 2:79 (comentario del propio al-Tabari)", ar_ref="تفسير الطبري، البقرة ٧٩", site=KSU, url=KSU_T+"sura2-aya79.html",
  es=["Con Su palabra «¡Ay de quienes escriben el libro con sus manos!», nuestro Señor hizo saber a Sus siervos creyentes [[k:que los rabinos de los judíos se encargan de escribir con sus manos mentiras e invenciones contra Dios]], a sabiendas y con intención de mentir sobre Dios, [[k:y luego las hacen pasar por algo que viene de Dios y que está en el Libro de Dios]], mintiendo y calumniando a Dios."],
  prueba="Es la postura del propio al-Tabari (m. 310 H) sobre 2:79: los rabinos escriben mentiras y las presentan como el Libro de Dios. Habla de escritos falsos atribuidos a Dios; no dice que el texto de la Torá haya desaparecido.",
  ojo="Para la «Torá quemada y restituida por Esdras», mira H11b y H11c; para lo de «la Torá que tienen hoy», H11d."),

 dict(id="H11b", year="310 H", who="al-Tabari (relato de Wahb)", postura="Mixta",
  title="La Torá «fue quemada y se perdió»… y Esdras la restituyó",
  ref="al-Tabari, Tarikh al-rusul wa-l-muluk, vol. 1, pp. 556–557 (ed. Abu al-Fadl Ibrahim)", ar_ref="تاريخ الطبري ١/٥٥٦–٥٥٧", site=SH, url="https://shamela.ws/book/9783/553",
  es=["Luego, cuando entraron en Siria, entraron sin tener consigo el pacto de Dios: [[k:la Torá les había sido arrebatada, y fue quemada y se perdió]]. Esdras (ʿUzayr) estaba entre los cautivos de Babilonia, y volvió a Siria llorándola noche y día; se había apartado de la gente y vagaba por el fondo de los valles y los desiertos llorando. Estando así, en su pena por la Torá y su llanto por ella, se le acercó un hombre mientras estaba sentado y le dijo: «Esdras, ¿qué te hace llorar?». Dijo: «Lloro por el Libro de Dios y Su pacto, que estaba entre nosotros. Nuestros pecados llevaron a que nuestro Señor se enfadara con nosotros y diera poder sobre nosotros a nuestro enemigo, que mató a nuestros hombres, arrasó nuestro país [[k:y quemó el Libro de Dios que estaba entre nosotros]], sin el cual no se arreglan ni esta vida ni la otra —o algo así dijo—. ¿Por qué voy a llorar, si no lloro por esto?». Dijo: «¿Te gustaría que te fuera devuelto?». Dijo: «¿Hay manera?». Dijo: «Sí. Vuelve, ayuna, purifícate y purifica tu ropa, y nos vemos aquí mañana». Esdras volvió, ayunó, se purificó y purificó su ropa, fue al lugar de la cita y se sentó. Aquel hombre —que era un ángel que Dios le había enviado— le trajo un recipiente con agua y le dio de beber de él, [[k:y la Torá quedó presente en su pecho]]. Volvió a los hijos de Israel y les dispuso la Torá, que reconocían, con lo lícito y lo ilícito, sus normas y sus obligaciones."],
  prueba="Al-Tabari recoge que la Torá se quemó y que Esdras la restituyó. En el relato, la Torá restituida es la verdadera, la que «reconocían».",
  ojo="No es opinión del propio al-Tabari: es un relato que transmite de Wahb ibn Munabbih vía Ibn Ishaq (empieza en la p. 548)."),

 dict(id="H11c", year="310 H", who="al-Tabari (relato de al-Suddi)", postura="Mixta",
  title="Esdras escribió la Torá entera… «la cotejaron y la encontraron igual»",
  ref="al-Tabari, Tafsir, sobre el Corán 9:30 (relato de al-Suddi, n.º 16622 en la numeración de Shakir)", ar_ref="تفسير الطبري، التوبة ٣٠", site=KSU, url=KSU_T+"sura9-aya30.html",
  es=["Esdras volvió, y era de los que más sabían de la Torá. Dijo: «Hijos de Israel, os he traído la Torá». Dijeron: «Esdras, tú no eras un mentiroso». Se ató una pluma a cada dedo y escribió con todos sus dedos, [[k:y escribió la Torá entera]]. Cuando volvieron los sabios, les contaron lo de Esdras; aquellos sabios sacaron los libros de la Torá que habían enterrado en los montes —estaban enterrados en tinajas—, [[k:los cotejaron con la Torá de Esdras y la encontraron igual]]."],
  prueba="En esta versión, la Torá que escribe Esdras coincide con los ejemplares antiguos que se habían enterrado: el relato defiende que el texto restituido es el mismo.",
  ojo="Es un relato de al-Suddi (m. 127 H) que recoge al-Tabari, no una opinión del propio al-Tabari."),

 dict(id="H11d", year="310 H", who="al-Tabari", postura="Mixta",
  title="«La Torá que tienen en sus manos hoy»: la frase existe, pero en un cálculo de cronología",
  ref="al-Tabari, Tarikh al-rusul wa-l-muluk, vol. 1, p. 17 (ed. Abu al-Fadl Ibrahim)", ar_ref="تاريخ الطبري ١/١٧", site=SH, url="https://shamela.ws/book/9783/15",
  es=["Los judíos sostienen que todo lo que consta para ellos —según lo que hay en la Torá, desde que Dios creó a Adán hasta el momento de la hégira, [[k:y eso en la Torá que tienen en sus manos hoy]]— son cuatro mil seiscientos cuarenta y dos años."],
  prueba="La expresión «la Torá que tienen en sus manos hoy» existe, pero aquí sirve para fechar el mundo, no para defender que haya una Torá falsa.",
  ojo="La Wikipedia en inglés, citando a Adang, dice que al-Tabari creía en otra Torá hecha por los rabinos y usada en su época. No hemos encontrado ese pasaje en árabe, y la nota de Wikipedia remite a páginas que hablan de otro autor (al-Qasim al-Rassi). No uses esa afirmación en el vídeo."),
]

AR = "archive.org (texto OCR de un escaneo)"
