HCARDS += [
 dict(id="H02a", year="68 H", who="Ibn Abbas (según Ibn Atiyya)", postura="Interpretación + libros añadidos",
  title="«Ibn Abbas sostuvo que su tergiversación es solo por interpretación, y el texto de la Torá permanece»",
  ref="Ibn Atiyya, al-Muharrar al-wajiz, sobre el Corán 2:75, vol. 1, p. 260 (ed. Awqaf de Catar)", ar_ref="المحرر الوجيز لابن عطية ١/٢٦٠", site=IW, url="https://www.islamweb.net/ar/library/content/207/51/",
  es=["Tergiversar una cosa es desviarla de un estado a otro. [[k:Ibn Abbas —Dios esté complacido con ambos— sostuvo que su tergiversación y su cambio son solo por la interpretación, y que el texto de la Torá permanece]]; [[a:y un grupo de sabios sostuvo que cambiaron palabras por su cuenta]], y que eso es posible en la Torá porque se les encomendó a ellos guardarla, y no es posible en el Corán porque Dios garantizó Él mismo su preservación."],
  prueba="Ibn Atiyya (m. 541 H) atribuye a Ibn Abbas, sin ponerlo en duda, la opinión de que solo hubo interpretación y de que el texto de la Torá permanece.",
  ojo="Ibn Atiyya recoge también la opinión contraria (en azul). Su propio veredicto está en H15."),

 dict(id="H10a", specs=["H10a1","H10a2"], year="255 H", who="al-Jahiz", postura="Texto alterado (según al-Qaduri; ver «Ojo»)",
  title="Los Evangelios, obra de «cuatro personas» que se contradicen… pero la Torá «sí, es verdad»",
  ref="al-Jahiz, al-Radd ʿala al-Nasara, en Rasaʾil al-Jahiz, ed. Harun, vol. 3, pp. 328 y 334", ar_ref="الرد على النصارى، رسائل الجاحظ ٣/٣٢٨ و٣/٣٣٤", site=SH, url="https://shamela.ws/book/10428/1054",
  es=["Nuestra respuesta: que recibieron su religión de cuatro personas: dos de ellas, apóstoles según dicen, Juan y Mateo; y dos de los que respondieron después, Marcos y Lucas. [[k:Y de estos cuatro no se puede descartar el error ni el olvido, ni la mentira deliberada]], ni que se pusieran de acuerdo, ni que pactaran repartirse la autoridad cediendo cada uno al otro la parte que le había fijado. Si dicen: «Eran demasiado virtuosos para mentir a sabiendas, demasiado cuidadosos para olvidar algo, demasiado elevados para equivocarse en la religión de Dios o descuidar un pacto», decimos: [[k:las diferencias entre sus relatos en el Evangelio y las contradicciones de sus libros]], y su desacuerdo sobre la naturaleza misma del Mesías, junto con la diferencia de sus leyes, prueban que tenemos razón sobre ellos y que vosotros no os habéis fijado.",
      "Si dicen: «Habladnos de Dios y de la Torá: [[k:¿no es verdad?]]», decimos: [[k:«Sí»]]. Dicen: «Pues en ella está “Israel es mi primogénito”, y todo lo que nos reprocháis es conocido en los libros». Decimos: [[k:«Esa gente fracasó por su poco conocimiento de los sentidos del lenguaje y por la mala traducción»]]…"],
  prueba="Al-Jahiz (m. 255 H) ataca los Evangelios como obra de cuatro hombres falibles que se contradicen, pero dice que la Torá es verdad y achaca los problemas a la mala interpretación y a la mala traducción.",
  ojo="En el texto conservado no usa «tergiversar» ni «cambiar» referido a las Escrituras. La etiqueta de al-Qaduri («alteración del texto») solo se sostiene en parte, y sobre todo para los Evangelios. Página 3/334: https://shamela.ws/book/10428/1060"),

 dict(id="H10b", year="s. III H", who="ʿAli ibn Rabban al-Tabari", postura="Texto alterado (pasajes concretos)",
  title="«Esto también lo considero una alteración y una corrupción en el Evangelio, por parte de los traductores y los copistas»",
  ref="ʿAli ibn Rabban al-Tabari, al-Din wa-l-dawla, ed. Nuwayhid (Beirut, 1973), p. 193", ar_ref="الدين والدولة لعلي بن ربن الطبري، ص ١٩٣", site=AR, url="https://archive.org/stream/0438-pdf_202101/",
  lang="árabe (OCR)",
  es=["…[si se refería con] estas palabras a los signos [hechos] por manos del Mesías; y si lo dijo de sí mismo, entonces el Mesías hizo lo contrario de lo que dijo y contradijo su primera palabra, y eso no le corresponde ni cabe pensarlo de él. [[k:Esto también lo considero una alteración y una corrupción en el Evangelio, por parte de los traductores y los copistas]]."],
  prueba="ʿAli ibn Rabban (s. III H), cristiano convertido al islam, señala pasajes concretos del Evangelio que cree corrompidos por traductores y copistas.",
  ojo="El texto en línea es un OCR con errores (letras persas, palabras partidas): compruébalo en la edición impresa. En el resto del libro argumenta a partir del texto bíblico: su acusación es sobre pasajes concretos, no sobre todo el libro."),

 dict(id="H10s", year="255 H – s. III", who="al-Jahiz e Ibn Rabban (según al-Qaduri)", postura="Texto alterado", secondary=True,
  title="La clasificación de al-Qaduri en la que se basa la fila de la tabla",
  ref="Samir al-Qaduri, Multaqa Ahl al-Tafsir (2005)", ar_ref="سمير القدوري، ملتقى أهل التفسير", site="mtafsir.net (artículo de un investigador actual)", url=MTU,
  es=["…[Se puede dividir a los autores en dos grandes grupos:] [[k:el grupo que sostiene que la alteración se produjo en el texto y en el sentido]] —sus partidarios son muchos; mencionamos algunos de cuyas opiniones tenemos noticia—: 1. [[k:al-Jahiz]]. 2. [[k:ʿAli ibn Rabban al-Tabari]]."],
  prueba="La fila de la tabla sobre al-Jahiz e Ibn Rabban se basa en esta clasificación del investigador marroquí Samir al-Qaduri. Las fuentes originales (H10a y H10b) solo la confirman en parte."),

 dict(id="H12a", year="403 H", who="al-Baqillani", postura="Interpretación (según al-Qaduri; ver H12b)",
  title="Que la Torá y el Evangelio vienen de Moisés y de Jesús se sabe «por necesidad»",
  ref="al-Baqillani, al-Tamhid, ed. Haydar (1987), pp. 158–159", ar_ref="التمهيد للباقلاني ص ١٥٨–١٥٩", site=SH, url="https://shamela.ws/book/6389/136",
  es=["Si alguien se empeñara en eso, negaría lo que se sabe por necesidad, y no habría que discutir con él; [[k:igual que si alguien pretendiera que la Torá y el Evangelio no forman parte de lo que apareció por medio de Moisés y de Jesús —la paz sea con ellos—: sería un obstinado y negaría]] [lo que se sabe por necesidad]."],
  prueba="Al-Baqillani (m. 403 H) pone como ejemplo de algo que se sabe por transmisión masiva (tawatur) que la Torá y el Evangelio vienen de Moisés y de Jesús. Es la base del argumento que le atribuye al-Qaduri.",
  ojo="Mira H12b y H12c antes de presentarlo como defensor de «solo el sentido»."),

 dict(id="H12b", specs=["H12b1","H12b2"], year="403 H", who="al-Baqillani", postura="Mixta (corrige la tabla)",
  title="«Tergiversaron, alteraron y cambiaron»… «el error y la tergiversación entran mucho en la transmisión»",
  ref="al-Baqillani, al-Tamhid, ed. Haydar (1987), pp. 208–209", ar_ref="التمهيد للباقلاني ص ٢٠٨–٢٠٩", site=SH, url="https://shamela.ws/book/6389/186",
  es=["…Y el reino de los hijos de Israel no se mantuvo porque le desobedecieron [a Moisés] en vida y después de su muerte, [[k:y tergiversaron, alteraron y cambiaron]]; y por eso desapareció su reino…",
      "…Ellos solo transmiten las palabras de Moisés, las traducen, las pasan de una lengua a otra y las interpretan, [[k:y el error y la tergiversación entran mucho en la transmisión]]; así que no se impone por necesidad que sea correcto lo que transmiten e interpretan…"],
  prueba="En el mismo libro, al-Baqillani dice que tergiversaron, alteraron y cambiaron, y que en la transmisión y traducción de las palabras de Moisés entra mucho error.",
  ojo="No hemos encontrado ningún pasaje suyo que limite el tahrif al sentido. En la tabla, su postura debe pasar a «mixta». Página 209: https://shamela.ws/book/6389/187"),

 dict(id="H12c", year="403 H", who="al-Baqillani", postura="Mixta (corrige la tabla)",
  title="«…después de haber tergiversado la Torá y cambiado la descripción del Mensajero»",
  ref="al-Baqillani, al-Intisar li-l-Qurʾan, ed. al-Qudah (2001), vol. 2, p. 669", ar_ref="الانتصار للقرآن للباقلاني ٢/٦٦٩", site=SH, url="https://shamela.ws/book/1397/617",
  es=["…Dios, ensalzado sea, niega eso de Sí mismo al decir «y no viene de Dios». Lo que pretendieron es que Dios había revelado la Torá así, tergiversada y cambiada, según hicieron creer a su gente baja, al vulgo y a la chusma; [[k:y lo pretendieron después de haber tergiversado la Torá y haberla alterado, y de haber cambiado la descripción del Mensajero y la mención de la buena nueva sobre él en la Torá]]. Y dijo Dios: «retuercen sus lenguas con el Libro para que lo creáis parte del Libro» (es decir, de la Torá)…"],
  prueba="Aquí al-Baqillani habla de un cambio concreto: la descripción del Profeta y la buena nueva sobre él, como Abu al-ʿAliya y Muqatil."),

 dict(id="H13a", specs=["H13a1","H13a2"], year="456 H", who="Ibn Hazm", postura="Texto alterado",
  title="En su propio libro: «Nos ha llegado que hay musulmanes que, por ignorancia, niegan que estén alterados»",
  ref="Ibn Hazm, al-Fisal fi l-milal wa-l-ahwaʾ wa-l-nihal, vol. 1, pp. 159–160 (Maktabat al-Khanji)", ar_ref="الفصل في الملل والأهواء والنحل ١/١٥٩–١٦٠", site=SH, url="https://shamela.ws/book/6521/151",
  es=["Dijo Abu Muhammad [Ibn Hazm]: [[k:Nos ha llegado que hay un grupo de musulmanes que, por ignorancia, niegan que la Torá y el Evangelio que tienen en sus manos los judíos y los cristianos estén alterados]]; [[a:y lo que les ha llevado a ello es lo poco que les importan los textos del Corán y de la Sunna]]. ¿Acaso no han oído la palabra de Dios: «Gente del Libro, ¿por qué revestís la verdad de falsedad y ocultáis la verdad a sabiendas?», y Su palabra: «y un grupo de ellos oculta la verdad a sabiendas»?",
      "…y Su palabra: «desplazan las palabras de su lugar»; y de esto hay muchísimo en el Corán. [[k:Y decimos a quien, entre los musulmanes, dice que su transmisión es masiva (tawātur), que da certeza y sirve de prueba]]: no hay duda de que ellos no discrepan en que [[a:lo que han transmitido de Moisés y de Jesús —la paz sea con ellos— no menciona en absoluto a Muhammad ﷺ]]…"],
  prueba="En su propio libro, Ibn Hazm (m. 456 H) reconoce que había musulmanes que negaban la alteración, y que algunos se apoyaban en la transmisión masiva (tawatur). Su respuesta es de contenido: si la transmisión fuera fiable, habría que aceptar también que no mencionan a Muhammad.",
  ojo="Ibn Hazm los llama ignorantes (en azul): muéstralo. Página 160: https://shamela.ws/book/6521/152"),

 dict(id="H14", year="486 H", who="ʿIsa ibn Sahl (según al-Qaduri)", postura="Interpretación", secondary=True,
  title="«Los judíos y los cristianos pueden decirle a Ibn Hazm…»: la única noticia de su libro perdido",
  ref="Samir al-Qaduri, Multaqa Ahl al-Tafsir (2005), resumiendo al-Tanbih ʿala shudhudh Ibn Hazm", ar_ref="سمير القدوري، ملتقى أهل التفسير (عن التنبيه على شذوذ ابن حزم)", site="mtafsir.net (artículo de un investigador actual)", url=MTU,
  es=["Frente a este grupo hay otro que no escribió un libro ni un capítulo propio sobre la tergiversación dentro de una refutación de la Gente del Libro, sino que se atuvo a una posición teórica: [[k:que la tergiversación se produjo en el sentido, porque creía que los libros de judíos y cristianos se transmitieron de forma masiva (tawātur)]]. Entre ellos: 1. el cadí Abu Bakr al-Baqillani (m. 403 H). 2. [[k:El cadí ʿIsa ibn Sahl al-Jayyani]] (m. 486 H). Su opinión está en su libro al-Tanbih ʿala shudhudh Ibn Hazm («Advertencia sobre las rarezas de Ibn Hazm»), [[k:donde reprocha a Ibn Hazm que diga que los libros de la Gente del Libro están alterados]], y le dice: «Los judíos y los cristianos pueden decirle a Ibn Hazm: seguimos religiones que nos trajeron nuestros mensajeros; si tú lo niegas, reniegas de lo que trae tu Libro (es decir, el Corán) y, según tu ley, debes morir. Y que algunos de los nuestros tergiversaran y otros se salieran no anula nuestra ley, igual que los jariyíes y los innovadores no anularon vuestra ley ni deshicieron vuestra religión con su aparición». Luego dice Ibn Sahl: «Esto es correcto y basta para mostrar la calumnia de Ibn Hazm… Si les hubiera argumentado que su religión y su ley quedaron abrogadas por lo que se reveló a Muhammad ﷺ, habría acertado y se habría librado del problema». [[k:Fin de sus palabras, en resumen]]."],
  prueba="ʿIsa ibn Sahl (m. 486 H), cadí andalusí, escribió contra Ibn Hazm reprochándole que dijera que los libros de la Gente del Libro están alterados.",
  ojo="Su libro no se ha publicado (solo hay un fragmento manuscrito en la Qarawiyyin de Fez). Esto es un resumen de al-Qaduri («en resumen»), no las palabras exactas de Ibn Sahl: preséntalo así."),

 dict(id="H15", specs=["H02a","H15b"], year="541 H", who="Ibn Atiyya", postura="Recoge ambas; su veredicto: «las dos cosas»",
  title="Recoge la postura de Ibn Abbas… y concluye: «no hay duda de que hicieron las dos cosas»",
  ref="Ibn Atiyya, al-Muharrar al-wajiz, sobre el Corán 2:75 (vol. 1, p. 260) y 5:13 (vol. 3, p. 130), ed. Awqaf de Catar", ar_ref="المحرر الوجيز ١/٢٦٠ و٣/١٣٠", site=IW, url="https://www.islamweb.net/ar/library/content/207/358/",
  es=["Tergiversar una cosa es desviarla de un estado a otro. [[k:Ibn Abbas —Dios esté complacido con ambos— sostuvo que su tergiversación y su cambio son solo por la interpretación, y que el texto de la Torá permanece]]; [[a:y un grupo de sabios sostuvo que cambiaron palabras por su cuenta]], y que eso es posible en la Torá porque se les encomendó a ellos guardarla, y no es posible en el Corán porque Dios garantizó Él mismo su preservación.",
      "Los sabios discrepan sobre el sentido de «desplazan las palabras»: [[k:un grupo —entre ellos Ibn Abbas— dijo: su tergiversación es por la interpretación; no tenían capacidad de cambiar las palabras de la Torá]], ni les era posible, [[k:y lo prueba que el versículo de la lapidación siguiera ahí]] y que necesitaran que el lector pusiera la mano encima. Otro grupo dijo: no, también tergiversaron las palabras y las cambiaron, e hicieron las dos cosas según pudieron. Dijo el cadí Abu Muhammad [Ibn Atiyya]: las palabras del Corán admiten los dos sentidos; Su palabra «¡Ay de quienes escriben el libro con sus manos!» implica cambio; [[a:y no hay duda de que hicieron las dos cosas]]."],
  prueba="Ibn Atiyya (m. 541 H) atribuye a Ibn Abbas la postura de «solo interpretación», con el argumento del versículo de la lapidación.",
  ojo="Su conclusión propia (en azul) es que hicieron las dos cosas. En el guion: el argumento de la lapidación es del grupo de Ibn Abbas que él recoge, no una prueba suya, y Ibn Atiyya no defiende que el texto esté intacto."),

 dict(id="H16", specs=["H16a","H16b"], year="606 H", who="Fajr al-Din al-Razi", postura="Interpretación (con matices)",
  title="«En un libro transmitido masivamente no es posible cambiar las palabras»",
  ref="al-Razi, al-Tafsir al-kabir, sobre el Corán 5:13 (vol. 11, p. 148) y 4:46 (vol. 10, p. 95), Dar al-Kutub al-ʿIlmiyya", ar_ref="التفسير الكبير للرازي ١١/١٤٨ و١٠/٩٥", site=IW, url="https://www.islamweb.net/ar/library/content/132/2103/",
  es=["Luego [Dios], ensalzado sea, menciona algunas consecuencias de esa dureza, y dice: «desplazan las palabras de su lugar». Esta tergiversación puede ser la interpretación falsa, y puede ser el cambio de las palabras; [[k:y ya hemos explicado antes que lo primero es más adecuado, porque en un libro transmitido de forma masiva (tawātur) no es posible cambiar las palabras]].",
      "Tercera cuestión: sobre cómo fue la tergiversación hay varias explicaciones. [[a:Una: que cambiaban una palabra por otra]], como cuando desplazaron de su lugar en la Torá [la descripción] «de estatura media» poniendo en su lugar «moreno y alto», o cambiaron «la lapidación» poniendo en su lugar «el castigo»; es como la palabra de Dios: «¡Ay de quienes escriben el libro con sus manos y luego dicen: esto viene de Dios!» (2:79). Si se dice: [[k:«¿Cómo es posible esto en un libro cuyas letras y palabras, una a una, alcanzaron la transmisión masiva conocida en Oriente y Occidente?»]], diríamos: quizá se pueda responder que eran pocos, y los que conocían el Libro eran poquísimos, y así pudieron hacer esa tergiversación. La segunda: que por tergiversación se entiende sembrar dudas falsas e interpretaciones corruptas, y desviar la palabra de su sentido verdadero a uno falso con artificios verbales, como hacen los innovadores de nuestro tiempo con los versículos que contradicen sus doctrinas; [[k:y esta es la más correcta]]."],
  prueba="Al-Razi (m. 606 H) prefiere entender el tahrif como interpretación falsa, porque un libro transmitido masivamente no puede cambiar sus palabras.",
  ojo="En 4:46 recoge primero la opinión del cambio de palabras (en azul), y al comentar 5:41 admite que también sacaron palabras del libro. Prefiere la interpretación, pero no excluye todo cambio. Página de 4:46: https://www.islamweb.net/ar/library/content/132/1770/"),

 dict(id="H19a", specs=["H19a1","H19a2"], year="804 H", who="Ibn al-Mulaqqin (su propio texto)", postura="Texto alterado (mayoritario en su escuela)",
  title="En su propio comentario: «lo que dijo sobre “yuḥarrifūn” es su opinión, y es una de las dos opiniones»",
  ref="Ibn al-Mulaqqin, al-Tawdih li-sharh al-Jamiʿ al-sahih, vol. 33, pp. 570 y 572 (Awqaf de Catar, 2008)", ar_ref="التوضيح لشرح الجامع الصحيح ٣٣/٥٧٠ و٥٧٢", site=IW, url="https://www.islamweb.net/ar/library/content/305/11700/",
  es=["«Yuḥarrifūn» (an-Nisāʾ 46): yuzīlūn. [[k:Y nadie elimina el texto de un libro de entre los libros de Dios, sino que lo tergiversan: lo interpretan de una forma que no es su interpretación]]. «Dirāsatuhum»: su recitación.",
      "Y el dicho de Ibn Abbas —Dios esté complacido con ambos— lo transmitió de él ʿAli ibn Abi Talha al-Shami en su Tafsir; [[k:y lo que dijo sobre «yuḥarrifūn» es su opinión, y es una de las dos opiniones]]; [[a:y que nuestros compañeros permitan limpiarse con las hojas de la Torá y el Evangelio, alegando que fueron cambiados, la contradice]]."],
  prueba="Es el texto del propio Ibn al-Mulaqqin (m. 804 H). La frase «es su opinión» va justo después de «el dicho de Ibn Abbas lo transmitió ʿAli ibn Abi Talha»: el sujeto no está claro y puede ser Ibn Abbas. La aclaración «es decir, al-Bujari» que aparece en Fath al-Bari (H19b, IH01) es de Ibn Hajar.",
  ojo="La cita de Ibn Hajar no coincide palabra por palabra con este texto impreso (habla de «tratar sus hojas sin respeto» en vez de «limpiarse con ellas»): puede ser otra versión del comentario o una cita libre. No digas que Ibn Hajar «manipuló» la cita. Página 570: https://www.islamweb.net/ar/library/content/305/11699/"),

 dict(id="H20a", specs=["H20a1","H20a2"], year="808 H", who="Ibn Khaldun", postura="Interpretación",
  title="«Ibn Abbas, según lo que transmite de él al-Bujari, dijo que eso es improbable… lo tergiversaron con la interpretación»",
  ref="Ibn Khaldun, Kitab al-ʿIbar (la Historia), vol. 2, pp. 7–8, ed. Shahada (Dar al-Fikr)", ar_ref="تاريخ ابن خلدون (العبر) ٢/٧–٨", site=SH, url="https://shamela.ws/book/12320/843",
  es=["En cuanto a lo que se dice de que sus sabios cambiaron pasajes de la Torá según los intereses de su religión: [[k:Ibn Abbas, según lo que transmite de él al-Bujari en su Sahih, dijo que eso es improbable]], [[k:y dijo: «Dios nos libre de que una nación de las naciones se proponga cambiar su Libro, revelado a su profeta»]], o algo con ese sentido. Y dijo: «solo lo cambiaron…",
      "…[[k:y lo tergiversaron con la interpretación]]». Lo atestigua la palabra de Dios: «y tienen la Torá, en la que está el juicio de Dios» (5:43); [[k:si hubieran cambiado las palabras de la Torá, no tendrían la Torá en la que está el juicio de Dios]]. Y lo que dice el noble Corán al atribuirles la tergiversación y el cambio [[k:se refiere a la interpretación]], [[a:salvo que hayan entrado cambios en las palabras por descuido y falta de precisión]]…"],
  prueba="Ibn Khaldun (m. 808 H) atribuye a Ibn Abbas, «según lo que transmite de él al-Bujari», que es improbable que cambiaran la Torá y que la tergiversación fue por interpretación, y lo apoya en el Corán 5:43. Es otro gran autor que atribuye esa idea a Ibn Abbas.",
  ojo="Está en Kitab al-ʿIbar (la Historia), no en la Muqaddima. Ibn Khaldun parafrasea: «Dios nos libre…» no es la redacción de Bujari. Admite cambios por descuido de copistas (en azul). Página 8: https://shamela.ws/book/12320/844"),

 dict(id="H20b", year="808 H", who="Ibn Khaldun (Muqaddima)", postura="Interpretación",
  title="«La afirmación de ese cambio no es la preferida por los investigadores… como mencionó al-Bujari»",
  ref="Ibn Khaldun, al-Muqaddima, introducción, vol. 1, p. 17 (edición de 2005, probablemente la de al-Shaddadi)", ar_ref="مقدمة ابن خلدون ١/١٧", site=AR, url="https://archive.org/stream/1_20230830_20230830_1222/1_djvu.txt",
  lang="árabe (OCR)",
  es=["Y si alguien objeta contra esa noticia que solo aparece en la Torá, y que los judíos la cambiaron, como es sabido, [respondemos]: [[k:la afirmación de ese cambio no es la preferida por los investigadores rigurosos]], y no ha de tomarse en su sentido literal, [[k:porque la costumbre impide que la gente de las religiones haga eso con sus escrituras divinas]], [[k:como mencionó al-Bujari en su Sahih]]. Así, este gran crecimiento de los hijos de Israel sería un milagro que rompe la costumbre…"],
  prueba="En la Muqaddima, Ibn Khaldun dice que el cambio de la Torá «no es la opinión preferida por los investigadores» y se remite a lo que dice al-Bujari en su Sahih. Es el pasaje que Rosenthal traduce: «unacceptable to thorough scholars».",
  ojo="Este pasaje solo está en algunos manuscritos (Rosenthal, nota 51) y falta en las ediciones basadas en Bulaq. Aquí se ve en un OCR de archive.org: compruébalo en la edición impresa antes de citarlo."),

 dict(id="H22a", year="885 H", who="al-Biqaʿi", postura="Uso positivo",
  title="Defiende citar la Torá y el Evangelio: «la prohibición se limita a lo que se sabe que fue cambiado»",
  ref="al-Biqaʿi, Nazm al-durar, sobre el Corán 2:34", ar_ref="نظم الدرر للبقاعي، البقرة ٣٤", site=IW, url="https://www.islamweb.net/ar/library/content/214/44/",
  es=["[[k:Si alguien rechaza que se cite la Torá o el Evangelio]], sin ver que lo mejor, en el debate, es responder a cada uno con lo que él mismo cree…",
      "Si algún shafiʿí entiende que sus imames prohibieron leer cualquiera de los libros antiguos, apoyándose en lo que dice el imam Abu al-Qasim al-Rafiʿi en su comentario —«los libros de la Torá y el Evangelio no se pueden aprovechar, porque cambiaron y alteraron», y lo mismo dijeron otros de la escuela—, [[k:se le responde: eso se limita a lo que se sabe que fue cambiado]].",
      "Nuestro maestro, el gran memorizador de su época, Abu al-Fadl ibn Hajar, trató a fondo la cuestión al final de su comentario de al-Bujari, y lo último que concluyó fue distinguir entre quien está firmemente asentado en las ciencias de la ley —a quien le está permitido mirarlo, porque extrae de ahí lo que aprovecha a los bien guiados— y los demás, a quienes no les está permitido. [[k:Y lo apoyó en que los imames, antiguos y modernos, los han mirado]] y han respondido a la gente de los dos Libros con lo que sacaban de ellos: [[k:si no fuera lícito, no lo habrían hecho]]…",
      "…Luego escribí sobre ello una buena obra, que titulé [[k:«al-Aqwal al-qawima fi hukm al-naql min al-kutub al-qadima»]] («Las opiniones rectas sobre citar los libros antiguos»)."],
  prueba="Al-Biqaʿi (m. 885 H), discípulo de Ibn Hajar, defiende citar la Torá y el Evangelio: la prohibición solo afecta a lo que se sabe que fue cambiado. Y se apoya en la conclusión de su maestro (IH14).",
  ojo="Su postura le costó una dura polémica: al-Sajawi escribió contra él un tratado titulado «La prohibición de citar la Torá y el Evangelio»."),

 dict(id="H22b", year="885 H", who="al-Biqaʿi", postura="Uso positivo",
  title="Un ejemplo: cita Deuteronomio 18 («os suscitaré un profeta de entre vuestros hermanos, como yo»)",
  ref="al-Biqaʿi, Nazm al-durar, sobre el Corán 7:157, vol. 8, pp. 107–108", ar_ref="نظم الدرر للبقاعي ٨/١٠٧–١٠٨", site=IW, url="https://www.islamweb.net/ar/library/content/214/1103/",
  es=["[[k:Y en la Torá también hay algo de esto, en el capítulo once del quinto libro]]: «Cuando entréis en la tierra que os da Dios, vuestro Señor, no hagáis como las obras de esos pueblos, y que no haya entre vosotros quien busque la enseñanza de los adivinos». Luego dice: «Porque esos pueblos cuya tierra heredáis obedecían a adivinos y astrólogos, pero a vosotros no os da eso Dios, vuestro Señor; [[k:sino que os suscitará un profeta de entre vuestros hermanos, como yo]]: obedeced a ese profeta, como pedisteis a Dios, vuestro Señor, en Horeb el día de la asamblea, cuando dijisteis: “Que no oigamos la voz de Dios, nuestro Señor, ni veamos este gran fuego, para no morir”. Y dijo el Señor: “Qué bien han hablado. Les suscitaré un profeta de entre sus hermanos, como tú; pondré Mis palabras en su boca y les dirá lo que Yo le mande; y a quien no acepte la palabra de ese profeta que habla en Mi nombre, Yo me vengaré de él y de su tribu”». Fin. Así lo he visto traducido en algunos ejemplares de la Torá."],
  prueba="Un ejemplo práctico: al-Biqaʿi cita la Torá (Dt 18) en su tafsir, tomada de «algunos ejemplares traducidos», como texto válido para argumentar."),

 dict(id="H22c", year="885 H", who="al-Biqaʿi", postura="Uso positivo",
  title="«…grandes imames, como al-Razi y al-Baghawi, han citado [mucho de ello]»",
  ref="al-Biqaʿi, al-Aqwal al-qawima fi hukm al-naql min al-kutub al-qadima, cap. 6, p. 437 (ed. de tesis de Umm al-Qura)", ar_ref="الأقوال القويمة في حكم النقل من الكتب القديمة، ص ٤٣٧", site=AR, url="https://archive.org/details/20250703_20250703_1416",
  lang="árabe (OCR)",
  es=["[Si lo que molesta a quien lo niega, por su poca familiaridad con los libros de los imames, es que se cite lo que hay en los libros] antiguos, [[k:este imam exegeta y otros grandes imames, como al-Razi y al-Baghawi, han citado]] [mucho de ello]."],
  prueba="En su tratado, al-Biqaʿi señala que grandes exegetas como al-Razi y al-Baghawi ya citaban material de los libros antiguos.",
  ojo="OCR con errores (letras persas). El «consenso tácito» que menciona la Wikipedia en inglés no es de al-Biqaʿi: es de su contemporáneo al-Kafiyaji (m. 879 H), en un aval que al-Biqaʿi reproduce en el capítulo 1 del tratado."),

 dict(id="H23", year="1891 d. C.", who="Rahmatullah al-Kairanawi", postura="Texto alterado",
  title="«La tergiversación literal, con sus tres tipos —cambio, adición y supresión—, está probada»",
  ref="Rahmatullah al-Kairanawi, Izhar al-haqq, vol. 2, p. 427 (ed. Malkawi, Riad, 1989)", ar_ref="إظهار الحق للكيرانوي ٢/٤٢٧", site=SH, url="https://shamela.ws/book/22721/413",
  es=["[La tergiversación] es de dos clases: literal y de sentido. [[a:Entre nosotros y los cristianos no hay disputa sobre la segunda]], porque todos ellos admiten que los judíos la cometieron en el Antiguo Testamento, en la interpretación de los versículos que, según ellos, aluden al Mesías, y en la interpretación de las normas que para los judíos son eternas; y los sabios protestantes reconocen que la cometieron los papistas en los libros de los dos Testamentos, igual que los papistas se lo reprochan con dureza a ellos; así que no hace falta probarla. Queda la primera, que los sabios protestantes niegan en apariencia con vehemencia para confundir a los musulmanes ignorantes, y han presentado en sus tratados pruebas engañosas y falsas para hacer dudar a los lectores; por eso necesita prueba, y quiero probarla en este libro, con la ayuda del Creador de la tierra y los cielos. Y digo: [[k:la tergiversación literal, en todas sus formas —es decir, cambiando palabras, añadiéndolas y suprimiéndolas—, está probada en los libros mencionados]], y expondré estos tres tipos por orden en tres apartados."],
  prueba="Kairanawi (m. 1891), en la obra de referencia de la polémica moderna, sostiene la tergiversación literal. Es la tesis de Tibyanan, y es del siglo XIX.",
  ojo="Fíjate en cómo construye el argumento: usa la crítica bíblica protestante y católica de su época, no fuentes islámicas antiguas."),

 dict(id="H24", year="Siglo XXI", who="Abdullah Saeed, académico musulmán", postura="Positiva", lang="inglés",
  title="«Si los textos siguen más o menos como en el siglo VII, el respeto que el Corán les mostró debería mantenerse hoy»",
  ref="Abdullah Saeed, «The Charge of Distortion of Jewish and Christian Scriptures», The Muslim World 92 (2002), citado en Wikipedia (inglés), «Tahrif»", ar_ref="", site="en.wikipedia.org (versión fija del 21-9-2026)", url="https://en.wikipedia.org/w/index.php?title=Tahrif&oldid=1375960251",
  es=["Aunque haya una corrupción textual asociada a la interpretación, las Escrituras mismas siguen siendo fiables y pueden considerarse «Libros de Dios». Para el Corán, el concepto de «Libro de Dios» se aplicaba con propiedad a las Escrituras de judíos y cristianos, aunque, desde el punto de vista musulmán, quizá no fueran «exactamente como eran» en tiempos de Moisés o de Jesús y, en algunos casos, estuvieran traducidas de las lenguas originales o narradas por alguien distinto del profeta que recibió la revelación. [[k:Como las Escrituras «reconocidas» de judíos y cristianos siguen siendo hoy en gran medida como eran en tiempos del Profeta]], es difícil sostener que las referencias coránicas a la Torá y al Evangelio se referían solo a una Torá y un Evangelio «puros», tal como existían en tiempos de Moisés y de Jesús. [[k:Si los textos siguen más o menos como estaban en el siglo VII]], el respeto que el Corán les mostró entonces debería mantenerse hoy."],
  prueba="Un académico musulmán contemporáneo llega a la misma conclusión: el argumento no es exclusivo de apologistas cristianos.",
  ojo="Wikipedia es una fuente secundaria; el artículo original está en H24b."),

 dict(id="H24b", year="Siglo XXI", who="Abdullah Saeed, académico musulmán", postura="Positiva", lang="inglés",
  title="El artículo original: «casi todos los intérpretes… vieron la corrupción en gran medida en la interpretación»",
  ref="Abdullah Saeed, «The Charge of Distortion of Jewish and Christian Scriptures», The Muslim World 92 (2002), pp. 419–436, conclusión, p. 434", ar_ref="", site="copia en PDF del artículo (alojada por terceros)", url="https://bible-quran-video.s3.amazonaws.com/Documents/The-Charge-of-Distortion-of-Jewish-and-Christian-Scriptures_Abdullah+Saeed.pdf",
  es=["…[[k:casi todos los intérpretes cuyas opiniones se examinan aquí parecen haber visto la corrupción como algo que reside en gran medida en la interpretación]]: por ejemplo, cambiar lo lícito (ḥalāl) en ilícito (ḥarām) o al revés, y ocultar u oscurecer lo que hay en la Escritura para confundir a otros, como en el caso del versículo 5:41. Una adición y una omisión deliberadas y a gran escala, en textos con una larga tradición de transmisión y ampliamente conocidos, serían difíciles. Rāzī y Qurṭubī, en particular, parecen sostener esta opinión. Aunque haya una corrupción textual asociada a la interpretación, las Escrituras mismas siguen siendo fiables y pueden considerarse «Libros de Dios»… [[k:Como las Escrituras «reconocidas» de judíos y cristianos siguen siendo hoy en gran medida como eran en tiempos del Profeta, es difícil sostener que las referencias coránicas a la Torá y al Evangelio se referían solo a una Torá y un Evangelio «puros»]], tal como existían en tiempos de Moisés y de Jesús. [[k:Si los textos siguen más o menos como estaban en el siglo VII, el respeto que el Corán les mostró entonces debería mantenerse hoy]]. [[k:Muchos intérpretes del Corán, de Ṭabarī a Rāzī, a Ibn Taymiyya e incluso a Quṭb, parecen inclinados a compartir esta opinión]]."],
  prueba="En la conclusión de su artículo, Saeed dice que casi todos los intérpretes que estudia (al-Tabari, al-Razi, al-Qurtubi, Ibn Taymiyya…) situaban la corrupción sobre todo en la interpretación.",
  ojo="La copia del PDF está alojada por terceros; para el vídeo basta con esta captura y la referencia de la revista."),
]
